cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void swish_kernel(const half* __restrict__ input,
                             half* __restrict__ output,
                             int64_t N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        float x = __half2float(input[idx]);
        float sig = 1.0f / (1.0f + expf(-x));
        float y = x * sig;
        output[idx] = __float2half(y);
    }
}

void swish_forward(at::Tensor input, at::Tensor output) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(output.is_cuda(), "output must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "input must be torch.float16");
    TORCH_CHECK(output.scalar_type() == at::ScalarType::Half,
                "output must be torch.float16");
    int64_t N = input.numel();

    const half* in_ptr = reinterpret_cast<const half*>(input.data_ptr<at::Half>());
    half* out_ptr = reinterpret_cast<half*>(output.data_ptr<at::Half>());

    const int threads = 256;
    const int blocks = static_cast<int>((N + threads - 1) / threads);

    swish_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(in_ptr, out_ptr, N);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel launch failed");
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("swish_forward", &swish_forward, "Swish forward (CUDA)");
}
'''

_swish_mod = load_inline(name='swish_cuda',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['swish_forward'],
                         verbose=False)

