    @staticmethod
    def forward(ctx, inp):
        ctx.save_for_backward(inp)
        out = torch.empty_like(inp)
        _swish_mod.swish_forward(inp, out)
        return out

    @staticmethod
    def backward(ctx, grad_output):
        inp, = ctx.saved_tensors
        # Derivative: sigmoid(x) + x * sigmoid(x) * (1 - sigmoid(x))
        sig = torch.sigmoid(inp)
